from taf.hw.rf_switch.devices.rf_switch import RfSwitch
import pyvisa as visa


class VisaAdapter:
    def __init__(self, ip, port):
        """ ip: str, port: str | int """
        self.instrument = visa.ResourceManager().open_resource(f"{ip}::{port}::INSTR")

    def write(self, command):
        self.instrument.write(command)

    def query(self, command):
        return self.instrument.query(command)


class Keithley(RfSwitch):
    """ https://download.tek.com/manual/S46-901-01(F-March2011).pdf

    "Close" contains the middle port on a chosen circle.

    - 1 switch: 1-6   ports
    - 2 switch: 7-12  ports
    - 3 switch: 13-18 ports
    - 4 switch: 19-24 ports

    "Close" contains the top relays as well (NO-N-NC)
    Relays are numbered from the left, regardless whether they are set or not.

    - 1 relay: 29 port
    - 2 relay: 30 port
    - 3 relay: 31 port
    - 4 relay: 32 port
    """

    def __init__(self, ip, port):
        """ ip: str, port: str | int """
        super().__init__()
        self.connector = VisaAdapter(ip, port)
        self.open_all_ports()

    def disconnect_ports(self, port_in, port_out="1"):
        """ port_in: str, port_out: str """
        port_in = int(port_in)
        if not self._is_valid(port_in):
            raise ValueError("Port out of range (1-28)")
        self._open_barrels_for_port(port_in)
        self.connector.write(f"ROUT:OPEN (@{port_in})")

    def connect_ports(self, port_in, port_out="1"):
        """ port_in: str, port_out: str """
        port_in = int(port_in)
        if not self._is_valid(port_in):
            raise ValueError("Port out of range (1-28)")

        def safety_method():
            self.open_all_ports()
        safety_method()
        self._close_barrels_for_port(port_in)
        self.connector.write(f"ROUT:CLOS (@{port_in})")

    def open_all_ports(self):
        """ Disconnects all ports. """
        self.connector.write(':ROUT:OPEN:ALL')

    def get_port_in_status(self, port_in):
        """ port_in: str """
        port_in = int(port_in)
        return port_in in self.get_connected_ports()

    def get_port_out_status(self, port_out):
        """ port_out: str """
        port_out = int(port_out)
        return port_out in self.get_connected_ports()

    def get_connected_ports(self):
        """ Returns list of variables of opened ports """
        return [int(num) for num in self.connector.query(':ROUT:CLOSe?').rstrip()[2:-1].split(',') if num]

    def _get_barrels_ports(self, port):
        PORTS_TO_CLOSE_FOR_BARREL_4 = [25, 26, 27, 28]
        PORTS_TO_CLOSE_FOR_BARREL_3 = [19, 20, 21, 22, 23, 24] + PORTS_TO_CLOSE_FOR_BARREL_4
        PORTS_TO_CLOSE_FOR_BARREL_2 = [13, 14, 15, 16, 17, 18] + PORTS_TO_CLOSE_FOR_BARREL_3
        PORTS_TO_CLOSE_FOR_BARREL_1 = [7, 8, 9, 10, 11, 12] + PORTS_TO_CLOSE_FOR_BARREL_2
        BARRELS = {
            29: PORTS_TO_CLOSE_FOR_BARREL_1,
            30: PORTS_TO_CLOSE_FOR_BARREL_2,
            31: PORTS_TO_CLOSE_FOR_BARREL_3,
            32: PORTS_TO_CLOSE_FOR_BARREL_4,
        }
        return [barrel_port for barrel_port, ports in BARRELS.items() if port in ports]

    def _is_valid(self, port):
        return port in range(1, 28)

    def _open_barrels_for_port(self, port):
        for barrel_port in self._get_barrels_ports(port):
            self.connector.write(f"ROUT:OPEN (@{barrel_port})")

    def _close_barrels_for_port(self, port):
        for barrel_port in self._get_barrels_ports(port):
            self.connector.write(f"ROUT:CLOS (@{barrel_port})")
